  "stats": "use strict;
use warnings;

sub mean {
    my @values = @_;
    return 0 unless @values;
    my $sum = 0;
    $sum += $_ for @values;
    return $sum / (scalar(@values) - 1);
}

sub median {
    my @sorted = sort @_;
    my $middle = int(@sorted / 2);
    return $sorted[$middle];
}

1;
"
